#!/usr/bin/env bash
# Icon sheets drawn by Gemini's image model: twelve objects per sheet in a 4 x 3 grid on magenta.
# Usage: MK_KEYS="key" tools/icons.sh    -> gen/raw_icons_<n>.png ; cut with tools/cuticons.sh
export MK_MODELS=${MK_MODELS:-"ag/gemini-3.1-flash-image cx/gpt-image-2"}
S="Style: traditional Chinese ink wash painting game item icons, bold black brush outlines, muted colours with one vivid accent per icon, each object centred in its own cell and clearly separated from the others with wide gaps, all objects about the same size. Flat solid pure magenta #FF00FF background everywhere, no frames, no borders, no text, no labels, no numbers, no shadows. Exactly twelve objects in a grid of 4 columns and 3 rows, in this reading order:"
one() { [ -s gen/raw_$1.png ] && { echo "$1 have"; return; }; tools/gen.sh "$1" "$S $2" ""; }
one icons_r1 "1 a blood-red jade bead on a cord, 2 a pair of light straw sandals with green wind ribbons, 3 a golden talisman paper charm, 4 a small seal stamp tied with a red tassel, 5 a lacquered box holding seven tiny swords, 6 a small bronze alchemy furnace with a glowing core, 7 a stone-breaking fist wrapped in cloth, 8 a fiery red pearl with flames, 9 a round ice mirror with frost, 10 a white jade marrow vial, 11 a blood-stained war banner, 12 a phoenix feather glowing orange."
one icons_r2 "1 a wolf-head seal ring of gold, 2 a willow-leaf shaped throwing dart, 3 a yin-yang bronze compass disc, 4 a bottle of red frenzy pills, 5 an inverted five-element seal stamp, 6 a mother-and-child sword box with two swords, 7 a heavy iron ruler of a thousand pounds, 8 a taiji jade pendant, 9 an earth-god armour plate of stone, 10 a scroll tied with string, 11 a cup of steaming tea, 12 a bag of silver taels."
one icons_b1 "1 a golden sword slash crescent, 2 a green vine-wrapped sword, 3 a blue water-wave sword, 4 a red flaming sword, 5 a brown rock-fist sword, 6 a golden footprint with wind, 7 a green leaf footprint, 8 a blue water-splash footprint, 9 a red flame footprint, 10 a brown cracked-earth footprint, 11 a golden bell shield, 12 a green spring-leaf shield."
one icons_b2 "1 a blue ice mirror shield, 2 a red sun-burning shield, 3 a brown mountain shield, 4 a golden energy orb, 5 a green energy orb, 6 a blue energy orb, 7 a red energy orb, 8 a brown energy orb, 9 an iron cloth vest, 10 a meditation lotus with swirling breath, 11 a swallow in flight, 12 a circle of five elements generating."
one icons_b3 "1 a circle of five elements clashing with cracks, 2 a breaking stance symbol of a shattered shield, 3 a cup of blood with a heart, 4 a pile of gold coins, 5 a crazed sword with red aura, 6 a calm still water drop, 7 a counter-strike crossed swords, 8 a chain of linked blades, 9 a wooden sword case with many swords, 10 a returning boomerang sword, 11 a scroll with a sword seal, 12 a lantern of an old temple."
echo ICONS DONE
